attributes.default:
({ name }) => {
		return fetch(`https://cdn.jsdelivr.net/npm/bootstrap-icons/icons/${name}.svg`, {
			mode: 'cors'
		}).then(async (response) => {
			const body = await response.text();

			if (!response.ok) throw new Error(body);

			return body;
		});
	}

